<script setup lang="ts">
import { onMounted, ref, nextTick, computed, reactive } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import type { ElTree, FormInstance } from 'element-plus'
import { api, save } from '../../api/client'
import type { Role, Menu } from '../../api/types'
import RequestError from '../../components/RequestError.vue'
const roles=ref<Role[]>([]),menus=ref<Menu[]>([]),selected=ref<Role>(),tree=ref<InstanceType<typeof ElTree>>(),loading=ref(false),saving=ref(false),error=ref<Error|null>(null),keyword=ref(''),dirty=ref(false)
const filtered=computed(()=>roles.value.filter(r=>`${r.roleName} ${r.roleCode}`.toLowerCase().includes(keyword.value.toLowerCase())))
async function load(){loading.value=true;error.value=null;try{[roles.value,menus.value]=await Promise.all([api<Role[]>('/admin/roles'),api<Menu[]>('/admin/menus')]);if(roles.value.length)await select(roles.value.find(r=>r.id===selected.value?.id)??roles.value[0])}catch(e){error.value=e as Error}finally{loading.value=false}}
async function select(role:Role){selected.value=role;dirty.value=false;await nextTick();tree.value?.setCheckedKeys(role.menuIds)}
async function submit(){if(!selected.value)return;saving.value=true;try{const menuIds=tree.value?.getCheckedKeys()??[];await save(`/admin/roles/${selected.value.id}/menus`,{menuIds},'PUT');selected.value.menuIds=menuIds.map(String);dirty.value=false;ElMessage.success('菜单权限已保存')}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}}
const roleDialog=ref(false), roleForm=ref<FormInstance>(), editingRole=ref<string|null>(null), roleSaving=ref(false), roleError=ref('')
const roleValues=reactive({roleCode:'',roleName:'',description:'',enabled:true})
function editRole(role?:Role){editingRole.value=role?.id??null;Object.assign(roleValues,{roleCode:role?.roleCode??'',roleName:role?.roleName??'',description:role?.description??'',enabled:role?.enabled??true});roleError.value='';roleDialog.value=true}
async function saveRole(){if(!await roleForm.value?.validate().catch(()=>false))return;roleSaving.value=true;roleError.value='';try{await save(editingRole.value?`/admin/roles/${editingRole.value}`:'/admin/roles',roleValues,editingRole.value?'PUT':'POST');roleDialog.value=false;ElMessage.success('角色已保存');await load()}catch(e){roleError.value=(e as Error).message}finally{roleSaving.value=false}}
async function deleteRole(){if(!selected.value)return;try{await ElMessageBox.confirm(`删除角色 ${selected.value.roleName}？仍被用户使用的角色不能删除。`,'删除角色',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await api(`/admin/roles/${selected.value.id}`,{method:'DELETE'});selected.value=undefined;ElMessage.success('角色已删除');await load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
onMounted(load)
</script>
<template><div class="page-head"><div><h1>角色管理</h1><p>按角色配置菜单访问权限</p></div><el-button type="primary" @click="editRole()">创建角色</el-button></div><RequestError :error="error" @retry="load"/><div v-loading="loading" class="roles-layout"><section class="surface panel"><div class="panel-head"><h2>角色列表</h2><small class="muted">{{ roles.length }} 个角色</small></div><el-input v-model="keyword" placeholder="搜索角色名称或代码" aria-label="搜索角色" clearable/><div class="role-list"><button v-for="r in filtered" :key="r.id" :class="{active:selected?.id===r.id}" @click="select(r)"><strong>{{ r.roleName }}</strong><small>{{ r.roleCode }}</small><el-tag v-if="!r.enabled" size="small" type="info">已停用</el-tag></button><el-empty v-if="!filtered.length" description="暂无角色" :image-size="50"/></div></section><section class="surface panel"><template v-if="selected"><div class="panel-head"><h2>角色信息</h2><div class="actions"><el-button text type="primary" @click="editRole(selected)">编辑信息</el-button><el-button v-if="!selected.systemRole" text type="danger" @click="deleteRole">删除</el-button><el-tag size="small" :type="selected.enabled?'success':'info'">{{ selected.enabled?'启用':'停用' }}</el-tag></div></div><el-descriptions :column="2" border><el-descriptions-item label="角色名称">{{ selected.roleName }}</el-descriptions-item><el-descriptions-item label="角色代码">{{ selected.roleCode }}</el-descriptions-item><el-descriptions-item label="说明" :span="2">{{ selected.description||'—' }}</el-descriptions-item></el-descriptions><div class="permission-head"><h2>菜单权限</h2><small class="muted">勾选可访问的菜单；组织归属不限制 V1 业务数据</small></div><el-tree ref="tree" :data="menus" node-key="id" show-checkbox check-strictly default-expand-all :props="{label:'name',children:'children'}" @check="dirty=true"><template #default="{data}"><span>{{ data.name }} <small v-if="!data.enabled" class="muted">（已停用）</small></span></template></el-tree><div class="permission-footer"><small class="muted">{{ dirty?'有未保存的权限变更':'权限与后端授权规则保持一致' }}</small><el-button type="primary" :loading="saving" :disabled="!dirty" @click="submit">保存菜单权限</el-button></div></template><el-empty v-else description="请选择角色"/></section></div><el-dialog v-model="roleDialog" :title="editingRole?'编辑角色':'创建角色'" width="520px" :close-on-click-modal="false" destroy-on-close><el-alert v-if="roleError" :title="roleError" type="error" :closable="false"/><el-form ref="roleForm" :model="roleValues" label-position="top" @submit.prevent="saveRole"><el-form-item label="角色代码" prop="roleCode" :rules="[{required:true,message:'请输入角色代码',trigger:'blur'},{pattern:/^[A-Z][A-Z0-9_]*$/,message:'使用大写字母、数字和下划线',trigger:'blur'}]"><el-input v-model="roleValues.roleCode" :readonly="!!editingRole" maxlength="64"/></el-form-item><el-form-item label="角色名称" prop="roleName" :rules="[{required:true,message:'请输入角色名称',trigger:'blur'}]"><el-input v-model="roleValues.roleName" maxlength="100"/></el-form-item><el-form-item label="说明"><el-input v-model="roleValues.description" type="textarea" maxlength="255"/></el-form-item><el-form-item label="状态"><el-switch v-model="roleValues.enabled" :disabled="roleValues.roleCode==='ADMIN'" active-text="启用" inactive-text="停用"/></el-form-item><div class="actions" style="justify-content:flex-end"><el-button @click="roleDialog=false">取消</el-button><el-button native-type="submit" type="primary" :loading="roleSaving">保存角色</el-button></div></el-form></el-dialog></template>
<style scoped>.roles-layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:16px}.role-list{display:grid;gap:4px;margin-top:12px}.role-list button{text-align:left;border:1px solid transparent;border-radius:6px;background:transparent;padding:12px;color:var(--text);position:relative}.role-list button:hover{background:#F5F6F5}.role-list button.active{background:#EEF1EF;border-color:transparent;color:#171A18;box-shadow:inset 2px 0 0 #181B19}.role-list strong{font-size:13px;display:block;font-weight:600}.role-list small{font-size:11px;color:var(--text-secondary);display:block;margin-top:4px}.permission-head{margin:24px 0 16px;display:grid;gap:6px}.permission-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;padding-top:20px;border-top:1px solid var(--border);margin-top:24px}:deep(.el-tree-node__content){height:36px}@media(max-width:767px){.roles-layout{grid-template-columns:1fr}.role-list{max-height:240px;overflow:auto}.permission-footer{align-items:flex-start;flex-direction:column}}</style>
